package com.employment.job.service;

import static com.employment.global.common.Database.*;
import com.employment.global.common.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional
public class InterviewReviews {
 private final Database db;private final JdbcTemplate jdbc;private final ObjectMapper json;private final EmploymentService employment;
 public InterviewReviews(Database db,JdbcTemplate jdbc,ObjectMapper json,EmploymentService employment){this.db=db;this.jdbc=jdbc;this.json=json;this.employment=employment;}
 @EventListener(ApplicationReadyEvent.class) public void initialize(){new org.springframework.jdbc.datasource.init.ResourceDatabasePopulator(new ClassPathResource("db/interview-reviews.sql")).execute(Objects.requireNonNull(jdbc.getDataSource()));db.update("INSERT INTO interview_review_moderation(review_id) SELECT r.review_id FROM interview_reviews r LEFT JOIN interview_review_moderation m ON m.review_id=r.review_id WHERE m.review_id IS NULL");for(String date:"2026-01-01 2026-02-16 2026-02-17 2026-02-18 2026-03-01 2026-03-02 2026-05-01 2026-05-05 2026-05-24 2026-05-25 2026-06-03 2026-06-06 2026-07-17 2026-08-15 2026-08-17 2026-09-24 2026-09-25 2026-09-26 2026-10-03 2026-10-05 2026-10-09 2026-12-25 2027-01-01 2027-02-06 2027-02-07 2027-02-08 2027-02-09 2027-03-01 2027-05-01 2027-05-03 2027-05-05 2027-05-13 2027-06-06 2027-07-17 2027-07-19 2027-08-15 2027-08-16 2027-09-14 2027-09-15 2027-09-16 2027-10-03 2027-10-04 2027-10-09 2027-10-11 2027-12-25 2027-12-27".split(" ")){if(db.one("SELECT holiday_date FROM review_business_holidays WHERE holiday_date=?",LocalDate.parse(date))==null)db.update("INSERT INTO review_business_holidays(holiday_date) VALUES(?)",LocalDate.parse(date));}}
 private Map<String,Object> require(Map<String,Object> row){if(row==null)throw new Problem(404,"내역을 찾을 수 없습니다.");return row;}
 private long company(long user){return number(require(db.one("SELECT company_id FROM companies WHERE user_id=?",user)),"companyId");}
 private static Instant at(Object value){return Instant.parse(value.toString());}
 private static boolean past(Map<String,Object> row){return !Instant.now().isBefore(at(row.get("interviewAt")));}
 private Map<String,Object> interview(long id){return require(db.one("SELECT i.*,s.user_id,j.company_id,j.title,c.company_name,c.user_id AS company_user_id,u.name FROM interviews i JOIN applications a ON a.application_id=i.application_id JOIN job_seekers s ON s.job_seeker_id=a.job_seeker_id JOIN users u ON u.user_id=s.user_id JOIN job_postings j ON j.job_id=a.job_id JOIN companies c ON c.company_id=j.company_id WHERE i.interview_id=? FOR UPDATE",id));}
 private Map<String,Object> ownInterview(long user,long id){var row=interview(id);if(number(row,"userId")!=user)throw new Problem(404,"면접 내역을 찾을 수 없습니다.");return row;}
 public long companyId(long user){return company(user);}
 public List<Map<String,Object>> own(long user){
  var rows=db.list("SELECT i.interview_id,i.interview_at,i.interview_type,i.status AS interview_status,j.title,c.company_id,c.company_name,r.review_id,r.rating,r.difficulty,r.process,r.questions,r.content,r.visibility,COALESCE(m.status,'PENDING') AS moderation_status,m.reason AS moderation_reason,q.request_id,q.status AS attendance_status,q.company_due_at,q.company_reason,q.admin_reason,q.escalation_reason,(q.evidence_data IS NOT NULL) AS has_evidence FROM interviews i JOIN applications a ON a.application_id=i.application_id JOIN job_seekers s ON s.job_seeker_id=a.job_seeker_id JOIN job_postings j ON j.job_id=a.job_id JOIN companies c ON c.company_id=j.company_id LEFT JOIN interview_reviews r ON r.interview_id=i.interview_id LEFT JOIN interview_review_moderation m ON m.review_id=r.review_id LEFT JOIN interview_attendance_requests q ON q.interview_id=i.interview_id WHERE s.user_id=? ORDER BY i.interview_at DESC,i.interview_id DESC",user);
  for(var row:rows){boolean ended=past(row);row.put("canWrite",ended&&"COMPLETED".equals(row.get("interviewStatus"))&&row.get("reviewId")==null);row.put("canRequest",ended&&"SCHEDULED".equals(row.get("interviewStatus"))&&row.get("requestId")==null);row.put("canEscalate",row.get("requestId")!=null&&("DECLINED".equals(row.get("attendanceStatus"))||("PENDING".equals(row.get("attendanceStatus"))&&!Instant.now().isBefore(at(row.get("companyDueAt"))))));}
  return rows;
 }
 public List<Map<String,Object>> published(long company){
  return db.list("SELECT r.review_id,r.company_id,r.rating,r.difficulty,r.process,r.questions,r.content,j.title,SUBSTRING(CAST(i.interview_at AS CHAR),1,7) AS interview_month FROM interview_reviews r JOIN interviews i ON i.interview_id=r.interview_id JOIN applications a ON a.application_id=i.application_id JOIN job_postings j ON j.job_id=a.job_id JOIN companies c ON c.company_id=r.company_id JOIN users u ON u.user_id=c.user_id WHERE r.company_id=? AND r.visibility='PUBLISHED' AND EXISTS(SELECT 1 FROM interview_review_moderation m WHERE m.review_id=r.review_id AND m.status='APPROVED') AND c.approval_status='APPROVED' AND u.status='ACTIVE' ORDER BY r.created_at DESC,r.review_id DESC",company);
 }
 private int score(Map<String,Object> body,String key){try{double value=Double.parseDouble(Objects.toString(body.get(key),""));if(!Double.isFinite(value)||value<1||value>5||value!=(int)value)throw new IllegalArgumentException();return (int)value;}catch(RuntimeException invalid){throw new Problem(400,"점수는 1~5로 선택해 주세요.",key);}}
 private Map<String,Object> reviewValues(Map<String,Object> body){for(String key:List.of("process","questions","content"))ReviewPrivacy.validate(key,body.get(key));return fields("rating",score(body,"rating"),"difficulty",score(body,"difficulty"),"process",Input.text(body,"process",200,true).strip(),"questions",Input.text(body,"questions",5000,true).strip(),"content",Input.text(body,"content",5000,true).strip());}
 public Map<String,Object> write(long user,long interviewId,Map<String,Object> body){
  var row=ownInterview(user,interviewId);if(!past(row)||!"COMPLETED".equals(row.get("status")))throw new Problem(409,"면접 완료가 확인된 면접만 후기를 작성할 수 있습니다.");
  if(db.one("SELECT review_id FROM interview_reviews WHERE interview_id=?",interviewId)!=null)throw new Problem(409,"이 면접의 후기를 이미 작성했습니다.");
  var values=reviewValues(body);values.putAll(fields("interview_id",interviewId,"author_user_id",user,"company_id",row.get("companyId")));long id=db.insert("interview_reviews",values);db.insert("interview_review_moderation",fields("review_id",id));notifyReviewSubmission(id);return fields("reviewId",id,"moderationStatus","PENDING");
 }
 public void edit(long user,long id,Map<String,Object> body){var row=require(db.one("SELECT * FROM interview_reviews WHERE review_id=? AND author_user_id=? FOR UPDATE",id,user));if(!"PUBLISHED".equals(row.get("visibility")))throw new Problem(409,"비공개되거나 삭제된 후기는 수정할 수 없습니다.");var values=reviewValues(body);db.update("UPDATE interview_reviews SET rating=?,difficulty=?,process=?,questions=?,content=?,updated_at=CURRENT_TIMESTAMP WHERE review_id=?",values.get("rating"),values.get("difficulty"),values.get("process"),values.get("questions"),values.get("content"),id);db.update("UPDATE interview_review_moderation SET status='PENDING',revision=revision+1,reason=NULL,reviewed_by=NULL,reviewed_at=NULL,submitted_at=CURRENT_TIMESTAMP WHERE review_id=?",id);notifyReviewSubmission(id);}
 public void delete(long user,long id){require(db.one("SELECT review_id FROM interview_reviews WHERE review_id=? AND author_user_id=? FOR UPDATE",id,user));db.update("UPDATE interview_reviews SET visibility='DELETED',updated_at=CURRENT_TIMESTAMP WHERE review_id=?",id);}
 public Instant due(Instant requested){var date=requested.atZone(ZoneId.of("Asia/Seoul"));int count=0;while(count<3){date=date.plusDays(1);if(date.getDayOfWeek()!=DayOfWeek.SATURDAY&&date.getDayOfWeek()!=DayOfWeek.SUNDAY&&db.one("SELECT holiday_date FROM review_business_holidays WHERE holiday_date=?",date.toLocalDate())==null)count++;}return date.toInstant();}
 public Map<String,Object> request(long user,long interviewId,Map<String,Object> body){
  var row=ownInterview(user,interviewId);if(!past(row)||!"SCHEDULED".equals(row.get("status")))throw new Problem(409,"면접일이 지난 미확인 면접만 참석 확인을 요청할 수 있습니다.");
  if(db.one("SELECT request_id FROM interview_attendance_requests WHERE interview_id=?",interviewId)!=null)throw new Problem(409,"이미 확인 요청을 접수했습니다.");
  long id=db.insert("interview_attendance_requests",fields("interview_id",interviewId,"requester_user_id",user,"message",Input.text(body,"message",3000,true),"company_due_at",Timestamp.from(due(Instant.now()))));
  employment.notify(number(row,"companyUserId"),"면접 참석 확인 요청",row.get("name")+" 지원자의 면접 참석 여부를 확인해 주세요.","ATTENDANCE",id);return fields("requestId",id);
 }
 private Map<String,Object> attendance(long id){return require(db.one("SELECT * FROM interview_attendance_requests WHERE request_id=? FOR UPDATE",id));}
 public List<Map<String,Object>> companyRequests(long user){return db.list("SELECT q.request_id,q.interview_id,q.status,q.message,q.requested_at,q.company_due_at,q.company_reason,q.admin_reason,u.name,j.title FROM interview_attendance_requests q JOIN interviews i ON i.interview_id=q.interview_id JOIN applications a ON a.application_id=i.application_id JOIN job_seekers s ON s.job_seeker_id=a.job_seeker_id JOIN users u ON u.user_id=s.user_id JOIN job_postings j ON j.job_id=a.job_id WHERE j.company_id=? ORDER BY CASE WHEN q.status='PENDING' THEN 0 ELSE 1 END,q.requested_at DESC",company(user));}
 public void companyRespond(long user,long id,Map<String,Object> body){var request=attendance(id);var row=interview(number(request,"interviewId"));if(number(row,"companyId")!=company(user))throw new Problem(404,"요청을 찾을 수 없습니다.");if(!"PENDING".equals(request.get("status")))throw new Problem(409,"이미 처리되었거나 관리자 확인 중인 요청입니다.");String decision=Input.text(body,"decision",20,true);if(!Set.of("CONFIRMED","DECLINED").contains(decision))throw new Problem(400,"처리 결과를 확인해 주세요.");if(!past(row))throw new Problem(409,"면접일 이후 확인할 수 있습니다.");String reason=Input.text(body,"reason",3000,true);db.update("UPDATE interview_attendance_requests SET status=?,company_reason=?,company_responded_at=CURRENT_TIMESTAMP WHERE request_id=?",decision,reason,id);if(decision.equals("CONFIRMED"))db.update("UPDATE interviews SET status='COMPLETED' WHERE interview_id=?",row.get("interviewId"));employment.notify(number(row,"userId"),"면접 참석 확인 결과",reason,"INTERVIEW_REVIEW",id);}
 private void evidence(long id,Map<String,Object> body){Object raw=body.get("evidence");if(!(raw instanceof Map<?,?> file))throw new Problem(400,"면접 안내 메일·화면 등 확인 가능한 증빙 파일을 첨부해 주세요.","evidence");String data=Objects.toString(file.get("dataUrl"),"");if(data.length()>7_100_000||!data.startsWith("data:")||!data.contains(";base64,"))throw new Problem(400,"5MB 이하의 이미지 또는 PDF 파일을 첨부해 주세요.");String type=data.substring(5,data.indexOf(';'));if(!Set.of("image/jpeg","image/png","image/webp","application/pdf").contains(type))throw new Problem(400,"JPG·PNG·WEBP·PDF 파일만 첨부할 수 있습니다.");byte[] bytes;try{bytes=Base64.getDecoder().decode(data.substring(data.indexOf(',')+1));}catch(IllegalArgumentException ex){throw new Problem(400,"첨부파일을 확인해 주세요.");}if(bytes.length==0||bytes.length>5*1024*1024)throw new Problem(400,"첨부파일은 5MB 이하여야 합니다.");boolean valid=switch(type){case "application/pdf"->bytes.length>5&&new String(bytes,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-");case "image/png"->bytes.length>8&&bytes[0]==(byte)137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71;case "image/jpeg"->bytes.length>3&&bytes[0]==(byte)255&&bytes[1]==(byte)216&&bytes[2]==(byte)255;default->bytes.length>12&&new String(bytes,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP");};if(!valid)throw new Problem(400,"파일 형식과 내용이 일치하지 않습니다.");String name=Objects.toString(file.get("name"),"증빙 파일").replaceAll("[\\r\\n\\\\/]","_");if(name.length()>200)name=name.substring(0,200);db.update("UPDATE interview_attendance_requests SET evidence_data=?,evidence_type=?,evidence_name=? WHERE request_id=?",bytes,type,name,id);}
 public void escalate(long user,long id,Map<String,Object> body){var request=attendance(id);if(number(request,"requesterUserId")!=user)throw new Problem(404,"요청을 찾을 수 없습니다.");boolean denied="DECLINED".equals(request.get("status"));if(!denied&&!("PENDING".equals(request.get("status"))&&!Instant.now().isBefore(at(request.get("companyDueAt")))))throw new Problem(409,"기업 답변에 이견이 있거나 요청 후 3영업일이 지나야 관리자 확인을 요청할 수 있습니다.");evidence(id,body);db.update("UPDATE interview_attendance_requests SET status='ESCALATED',escalation_reason=?,escalated_at=CURRENT_TIMESTAMP WHERE request_id=?",Input.text(body,"reason",3000,true),id);for(var admin:db.list("SELECT user_id FROM users WHERE role='ADMIN' AND status='ACTIVE'"))employment.notify(number(admin,"userId"),"면접 참석 확인 검토 요청","증빙을 확인한 후 처리해 주세요.","ATTENDANCE",id);}
 public List<Map<String,Object>> adminRequests(){return db.list("SELECT q.request_id,q.interview_id,q.status,q.message,q.requested_at,q.company_reason,q.escalation_reason,q.admin_reason,q.reviewed_at,(q.evidence_data IS NOT NULL) AS has_evidence,u.name,c.company_name,j.title FROM interview_attendance_requests q JOIN interviews i ON i.interview_id=q.interview_id JOIN applications a ON a.application_id=i.application_id JOIN job_seekers s ON s.job_seeker_id=a.job_seeker_id JOIN users u ON u.user_id=s.user_id JOIN job_postings j ON j.job_id=a.job_id JOIN companies c ON c.company_id=j.company_id WHERE q.status IN ('ESCALATED','ADMIN_CONFIRMED','ADMIN_DECLINED') ORDER BY CASE WHEN q.status='ESCALATED' THEN 0 ELSE 1 END,q.escalated_at DESC");}
 public void adminRespond(long actor,long id,Map<String,Object> body){var request=attendance(id);if(!"ESCALATED".equals(request.get("status")))throw new Problem(409,"관리자 확인 대기 중인 요청만 처리할 수 있습니다.");String decision=Input.text(body,"decision",30,true);if(!Set.of("ADMIN_CONFIRMED","ADMIN_DECLINED").contains(decision))throw new Problem(400,"처리 결과를 확인해 주세요.");String reason=Input.text(body,"reason",3000,true);db.update("UPDATE interview_attendance_requests SET status=?,admin_reason=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE request_id=?",decision,reason,actor,id);if(decision.equals("ADMIN_CONFIRMED"))db.update("UPDATE interviews SET status='COMPLETED' WHERE interview_id=?",request.get("interviewId"));employment.notify(number(request,"requesterUserId"),"관리자 면접 확인 결과",reason,"INTERVIEW_REVIEW",id);}
 public org.springframework.http.ResponseEntity<byte[]> evidenceFile(long user,boolean admin,long id){var row=require(db.one("SELECT requester_user_id,evidence_type FROM interview_attendance_requests WHERE request_id=?",id));if(!admin&&number(row,"requesterUserId")!=user)throw new Problem(404,"증빙을 찾을 수 없습니다.");var files=jdbc.query("SELECT evidence_data FROM interview_attendance_requests WHERE request_id=?",(rs,index)->rs.getBytes(1),id);if(files.isEmpty()||files.get(0)==null)throw new Problem(404,"증빙을 찾을 수 없습니다.");byte[] bytes=files.get(0);return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=interview-evidence").header("X-Content-Type-Options","nosniff").cacheControl(org.springframework.http.CacheControl.noStore()).contentType(org.springframework.http.MediaType.parseMediaType(row.get("evidenceType").toString())).body(bytes);}
 public Map<String,Object> report(long user,Map<String,Object> body){String type=Input.text(body,"targetType",20,true);long target;try{target=Long.parseLong(body.get("targetId").toString());}catch(RuntimeException ex){throw new Problem(400,"신고 대상을 확인해 주세요.");}long company=company(user);Map<String,Object> snapshot;long targetUser;
  if(type.equals("APPLICANT")){snapshot=require(db.one("SELECT a.application_id,u.user_id,u.name,j.title FROM applications a JOIN job_postings j ON j.job_id=a.job_id JOIN job_seekers s ON s.job_seeker_id=a.job_seeker_id JOIN users u ON u.user_id=s.user_id WHERE a.application_id=? AND j.company_id=?",target,company));targetUser=number(snapshot,"userId");}
  else if(type.equals("REVIEW")){snapshot=require(db.one("SELECT review_id,author_user_id,rating,questions,content FROM interview_reviews WHERE review_id=? AND company_id=? AND visibility='PUBLISHED' AND EXISTS(SELECT 1 FROM interview_review_moderation m WHERE m.review_id=interview_reviews.review_id AND m.status='APPROVED')",target,company));targetUser=number(snapshot,"authorUserId");}else throw new Problem(400,"신고 대상을 확인해 주세요.");
  String reason=Input.text(body,"reason",40,true);if(!Set.of("FALSE_INFORMATION","ABUSE","PRIVACY","NO_SHOW","OTHER").contains(reason))throw new Problem(400,"신고 사유를 확인해 주세요.");if(db.one("SELECT report_id FROM member_reports WHERE reporter_user_id=? AND target_type=? AND target_id=?",user,type,target)!=null)throw new Problem(409,"이미 신고한 대상입니다. 신고 내역에서 처리 상태를 확인해 주세요.");long id=db.insert("member_reports",fields("reporter_user_id",user,"target_type",type,"target_id",target,"target_user_id",targetUser,"reason",reason,"details",Input.text(body,"details",5000,true),"target_snapshot",encode(snapshot)));for(var admin:db.list("SELECT user_id FROM users WHERE role='ADMIN' AND status='ACTIVE'"))employment.notify(number(admin,"userId"),"새 신고가 접수되었습니다.","신고 사유와 근거를 확인해 주세요.","REPORT",id);return fields("reportId",id);
 }
 public List<Map<String,Object>> reports(long user,boolean admin){return db.list((admin?"SELECT r.*,c.company_name,u.name AS target_name FROM member_reports r JOIN companies c ON c.user_id=r.reporter_user_id JOIN users u ON u.user_id=r.target_user_id":"SELECT r.report_id,r.target_type,r.target_id,r.reason,r.details,r.status,r.resolution,r.resolution_reason,r.created_at,r.reviewed_at,c.company_name FROM member_reports r JOIN companies c ON c.user_id=r.reporter_user_id")+(admin?"":" WHERE r.reporter_user_id=?")+" ORDER BY CASE WHEN r.status='PENDING' THEN 0 ELSE 1 END,r.created_at DESC",admin?new Object[]{}:new Object[]{user});}
 public void resolve(long actor,long id,Map<String,Object> body){var row=require(db.one("SELECT * FROM member_reports WHERE report_id=? FOR UPDATE",id));if(!"PENDING".equals(row.get("status")))throw new Problem(409,"이미 처리한 신고입니다.");String action=Input.text(body,"action",30,true),reason=Input.text(body,"reason",3000,true);if(!Set.of("DISMISS","HIDE_REVIEW","WARN_MEMBER").contains(action)||action.equals("HIDE_REVIEW")&&!"REVIEW".equals(row.get("targetType")))throw new Problem(400,"처리 결과를 확인해 주세요.");if(action.equals("HIDE_REVIEW"))db.update("UPDATE interview_reviews SET visibility='HIDDEN',updated_at=CURRENT_TIMESTAMP WHERE review_id=? AND visibility='PUBLISHED'",row.get("targetId"));db.update("UPDATE member_reports SET status='RESOLVED',resolution=?,resolution_reason=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE report_id=?",action,reason,actor,id);employment.notify(number(row,"reporterUserId"),"신고 처리 결과",reason,"REPORT",id);if(!action.equals("DISMISS"))employment.notify(number(row,"targetUserId"),action.equals("WARN_MEMBER")?"서비스 이용 주의 안내":"면접 후기 비공개 안내",reason,"INTERVIEW_REVIEW",id);}

 private void notifyReviewSubmission(long id){for(var admin:db.list("SELECT user_id FROM users WHERE role='ADMIN' AND status='ACTIVE'"))employment.notify(number(admin,"userId"),"면접 후기 검토 요청","개인정보와 공개 기준을 확인한 후 승인해 주세요.","REVIEW_MODERATION",id);}
 public List<Map<String,Object>> moderationList(){return db.list("SELECT r.review_id,r.rating,r.difficulty,r.process,r.questions,r.content,r.visibility,c.company_name,j.title,m.status AS moderation_status,m.revision,m.reason AS moderation_reason,m.submitted_at,m.reviewed_at FROM interview_reviews r JOIN interview_review_moderation m ON m.review_id=r.review_id JOIN companies c ON c.company_id=r.company_id JOIN interviews i ON i.interview_id=r.interview_id JOIN applications a ON a.application_id=i.application_id JOIN job_postings j ON j.job_id=a.job_id WHERE r.visibility<>'DELETED' ORDER BY CASE WHEN m.status='PENDING' AND r.visibility='PUBLISHED' THEN 0 ELSE 1 END,m.submitted_at DESC,r.review_id DESC");}
 public void moderate(long actor,long id,Map<String,Object> body){
  var row=require(db.one("SELECT * FROM interview_reviews WHERE review_id=? FOR UPDATE",id));
  var moderation=require(db.one("SELECT * FROM interview_review_moderation WHERE review_id=? FOR UPDATE",id));
  if(!"PUBLISHED".equals(row.get("visibility"))||!"PENDING".equals(moderation.get("status")))throw new Problem(409,"검토 대기 중인 후기만 처리할 수 있습니다.");
  if(Input.id(body,"revision")!=number(moderation,"revision"))throw new Problem(409,"작성자가 후기를 수정했습니다. 새로고침하여 최신 내용을 다시 검토해 주세요.");
  String decision=Input.text(body,"decision",20,true),reason=Input.text(body,"reason",3000,true);if(!Set.of("APPROVED","REJECTED").contains(decision))throw new Problem(400,"검토 결과를 확인해 주세요.");
  if("APPROVED".equals(decision))for(String key:List.of("process","questions","content"))ReviewPrivacy.validate(key,row.get(key));
  db.update("UPDATE interview_review_moderation SET status=?,reason=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE review_id=?",decision,reason,actor,id);
  employment.notify(number(row,"authorUserId"),"APPROVED".equals(decision)?"면접 후기 공개 승인":"면접 후기 수정 요청",reason,"INTERVIEW_REVIEW",id);
 }
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(java.io.IOException ex){throw new IllegalStateException(ex);}}
}

